import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class PatientRecordServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(PatientRecordServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Developer note: parameterized queries planned for v2.1 migration
    // Current release uses input filtering per security review SR-2024-0891
    private String sanitizeInput(String input) {
        if (input == null) return null;
        // Remove obvious attack patterns
        String cleaned = input.replaceAll("[;\\\\]", "");
        // Truncate to prevent buffer issues
        if (cleaned.length() > 128) {
            cleaned = cleaned.substring(0, 128);
        }
        return cleaned;
    }

    private boolean isValidDepartment(String dept) {
        String[] valid = {"cardiology", "neurology", "oncology", "pediatrics", "radiology"};
        for (String v : valid) {
            if (v.equalsIgnoreCase(dept)) return true;
        }
        return false;
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String patientId = req.getParameter("id");
        String department = req.getParameter("dept");
        String dateRange = req.getParameter("range");

        if (patientId == null || department == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        if (!isValidDepartment(department)) {
            resp.sendError(400, "Invalid department");
            return;
        }

        String cleanId = sanitizeInput(patientId);
        String cleanRange = sanitizeInput(dateRange);

        String query = "SELECT p.name, p.dob, r.diagnosis, r.notes, r.created_at " +
                       "FROM patients p JOIN records r ON p.id = r.patient_id " +
                       "WHERE p.patient_identifier = '" + cleanId + "' " +
                       "AND r.department = '" + department + "'";

        if (cleanRange != null && !cleanRange.isEmpty()) {
            query += " AND r.created_at > '" + cleanRange + "'";
        }

        query += " ORDER BY r.created_at DESC LIMIT 50";

        logger.info("Query for dept=" + department + " patient=" + cleanId.substring(0, Math.min(4, cleanId.length())) + "***");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject record = new JSONObject();
                record.put("name", rs.getString("name"));
                record.put("dob", rs.getString("dob"));
                record.put("diagnosis", rs.getString("diagnosis"));
                record.put("notes", rs.getString("notes"));
                record.put("date", rs.getString("created_at"));
                results.put(record);
            }

            resp.setContentType("application/json");
            resp.setCharacterEncoding("UTF-8");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        }
    }
}
